1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { randomBytes } from "node:crypto";
5	import { resolveTxt, resolveMx } from "node:dns/promises";
6	import { z } from "zod";
7	import { db } from "./db";
8	import { requireUser } from "./auth";
9	import { requireArea } from "./rbac";
10	import { checkRateLimit } from "./rate-limit";
11	import { debitWallet, InsufficientBalanceError } from "./wallet";
12	import { addMonths } from "./billing-terms";
13	import { encryptSecret } from "./crypto-box";
14	import { currentPromo, promoPriceCents } from "./promotions";
15	import {
16	  mailcowConfigured,
17	  mcCreateDomain,
18	  mcDomainExists,
19	  mcCreateMailbox,
20	  mcDeleteMailbox,
21	  mcSetMailboxActive,
22	  mcGetDkim,
23	} from "./mailcow";
24	
25	/**
26	 * Mail-platform DNS constants. Customers with a domain registered ELSEWHERE
27	 * publish these at their registrar so mail flows through the Nxeon mail server;
28	 * customers whose domain is inside Nxeon have this managed for them.
29	 */
30	const MAIL_HOST = "mail.nxeon.cloud";
31	const MAIL_MX_PRIORITY = 10;
32	const SPF_VALUE = "v=spf1 include:nxeon.cloud ~all";
33	const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
34	const DKIM_SELECTOR = "dkim";
35	
36	// A syntactically valid registrable domain (labels, no scheme, no trailing dot).
37	const domainRe =
38	  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
39	
40	export type DnsRecord = {
41	  type: "TXT" | "MX";
42	  label: string; // human label for the row
43	  host: string; // record host / name
44	  value: string;
45	  priority?: number;
46	  note?: string;
47	};
48	
49	/**
50	 * Business Email — mailbox hosting per registered domain.
51	 *
52	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
53	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
54	 * which debits the wallet, then manages individual `Mailbox` rows under it.
55	 *
56	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
57	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
58	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
59	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
60	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
61	 * order flow; the row persists and can be retried via retryMailboxProvision.
62	 *
63	 * This module owns:
64	 *   - orderEmailHosting (customer subscribe)
65	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
66	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
67	 */
68	
69	type Result = { error?: string; ok?: boolean };
70	
71	/**
72	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
73	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
74	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
75	 * can be picked up once the integration is wired.
76	 */
77	async function provisionMailboxOnMailcow(mailbox: {
78	  id: string;
79	  address: string;
80	  quotaMB: number | null;
81	  subscription: { domainName: string };
82	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
83	  if (!mailcowConfigured()) return "PROVISIONING";
84	
85	  const [localPart] = mailbox.address.split("@");
86	  const domain = mailbox.subscription.domainName;
87	  const quotaMB = mailbox.quotaMB ?? 1024;
88	
89	  try {
90	    // Ensure the mail domain exists before adding the mailbox.
91	    if (!(await mcDomainExists(domain))) {
92	      // A concurrent create or pre-existing domain can still error here; ignore
93	      // and let the mailbox add be the real signal.
94	      await mcCreateDomain(domain).catch(() => {});
95	    }
96	
97	    const password = randomBytes(18).toString("base64url");
98	    await mcCreateMailbox({
99	      localPart,
100	      domain,
101	      name: mailbox.address,
102	      password,
103	      quotaMB,
104	    });
105	
106	    await db.mailbox.update({
107	      where: { id: mailbox.id },
108	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
109	    });
110	    return "ACTIVE";
111	  } catch (e) {
112	    await db.mailbox
113	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
114	      .catch(() => {});
115	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
116	    return "FAILED";
117	  }
118	}
119	
120	// ---------- Admin CRUD (billing area) ----------
121	
122	const planSchema = z.object({
123	  id: z.string().optional(),
124	  name: z.string().min(2).max(80),
125	  mailboxes: z.coerce.number().int().min(1).max(100000),
126	  storageGB: z.coerce.number().int().min(1).max(100000),
127	  priceCents: z.coerce.number().int().min(0).max(100000000),
128	  termMonths: z.coerce.number().int().min(1).max(36),
129	  sortOrder: z.coerce.number().int().min(0).max(100000),
130	});
131	
132	/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
133	export async function adminSaveEmailPlan(
134	  prev: Result | undefined,
135	  formData: FormData,
136	): Promise<Result> {
137	  const admin = await requireArea("billing");
138	
139	  const parsed = planSchema.safeParse({
140	    id: formData.get("id") || undefined,
141	    name: formData.get("name"),
142	    mailboxes: formData.get("mailboxes"),
143	    storageGB: formData.get("storageGB"),
144	    priceCents: formData.get("priceCents"),
145	    termMonths: formData.get("termMonths"),
146	    sortOrder: formData.get("sortOrder") ?? 0,
147	  });
148	  if (!parsed.success) {
149	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
150	  }
151	  const d = parsed.data;
152	  const active = formData.get("active") === "on";
153	
154	  const data = {
155	    name: d.name.trim(),
156	    mailboxes: d.mailboxes,
157	    storageGB: d.storageGB,
158	    priceCents: d.priceCents,
159	    termMonths: d.termMonths,
160	    active,
161	    sortOrder: d.sortOrder,
162	  };
163	
164	  if (d.id) {
165	    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
166	    if (!existing) return { error: "Tier not found." };
167	    await db.emailPlan.update({ where: { id: d.id }, data });
168	  } else {
169	    await db.emailPlan.create({ data });
170	  }
171	
172	  await db.auditLog.create({
173	    data: {
174	      userId: admin.id,
175	      action: d.id ? "emailplan.update" : "emailplan.create",
176	      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
177	    },
178	  });
179	  revalidatePath("/admin/email-plans");
180	  return { ok: true };
181	}
182	
183	/** Flip a tier's active flag. */
184	export async function adminToggleEmailPlan(id: string): Promise<void> {
185	  const admin = await requireArea("billing");
186	  const plan = await db.emailPlan.findUnique({ where: { id } });
187	  if (!plan) return;
188	  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
189	  await db.auditLog.create({
190	    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
191	  });
192	  revalidatePath("/admin/email-plans");
193	}
194	
195	/** Delete a tier. Refused while subscriptions reference it. */
196	export async function adminDeleteEmailPlan(id: string): Promise<Result> {
197	  const admin = await requireArea("billing");
198	  const plan = await db.emailPlan.findUnique({
199	    where: { id },
200	    include: { _count: { select: { subscriptions: true } } },
201	  });
202	  if (!plan) return { error: "Tier not found." };
203	  if (plan._count.subscriptions > 0) {
204	    return {
205	      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
206	    };
207	  }
208	  await db.emailPlan.delete({ where: { id } });
209	  await db.auditLog.create({
210	    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
211	  });
212	  revalidatePath("/admin/email-plans");
213	  return { ok: true };
214	}
215	
216	// ---------- Customer ordering ----------
217	
218	/**
219	 * Subscribe one of the caller's registered domains to an email plan. Validates
220	 * domain ownership + plan availability, then atomically debits the wallet and
221	 * creates the EmailSubscription with an expiry set from the plan term.
222	 *
223	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
224	 * provisioned with a mail provider yet — that integration is pending, and the
225	 * UI surfaces every mailbox as "provisioning" until it lands.
226	 */
227	export async function orderEmailHosting(
228	  domainName: string,
229	  emailPlanId: string,
230	): Promise<Result> {
231	  const user = await requireUser();
232	
233	  const name = String(domainName ?? "")
234	    .trim()
235	    .toLowerCase()
236	    .replace(/\.$/, "");
237	  if (!name) return { error: "Enter a domain." };
238	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
239	
240	  // Is the domain registered inside Nxeon? If so we control its DNS and can
241	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
242	  // verified via DNS before mail flows.
243	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
244	  const external = !inAccount;
245	
246	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
247	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
248	
249	  // One subscription per domain — refuse a duplicate.
250	  const dupe = await db.emailSubscription.findFirst({
251	    where: { userId: user.id, domainName: name, status: { not: "CANCELLED" } },
252	  });
253	  if (dupe) return { error: "This domain already has an email subscription." };
254	
255	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
256	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
257	  // strikethrough shown on the pricing page is the real renewal price and this
258	  // discounted value is the real first-term price — displayed === charged.
259	  const promo = currentPromo(new Date());
260	  const chargeCents = promoPriceCents(plan.priceCents, promo);
261	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
262	  if (user.balanceCents < chargeCents) {
263	    return { error: "Insufficient balance. Top up your wallet first." };
264	  }
265	
266	  try {
267	    await db.$transaction(async (tx) => {
268	      await debitWallet(tx, user.id, chargeCents);
269	      await tx.walletTransaction.create({
270	        data: {
271	          userId: user.id,
272	          amountCents: -chargeCents,
273	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
274	        },
275	      });
276	      await tx.emailSubscription.create({
277	        data: {
278	          userId: user.id,
279	          domainName: name,
280	          emailPlanId: plan.id,
281	          status: "ACTIVE",
282	          autoRenew: true,
283	          expiresAt: addMonths(new Date(), plan.termMonths),
284	          // In-account domains: we control DNS, so treat as verified now. External
285	          // domains: not verified until the customer publishes DNS + we confirm it.
286	          external,
287	          verified: !external,
288	          verifiedAt: external ? null : new Date(),
289	          verifyToken: external ? randomBytes(24).toString("hex") : null,
290	        },
291	      });
292	    });
293	  } catch (e) {
294	    if (e instanceof InsufficientBalanceError) {
295	      return { error: "Insufficient balance. Top up your wallet first." };
296	    }
297	    throw e;
298	  }
299	
300	  await db.auditLog.create({
301	    data: {
302	      userId: user.id,
303	      action: "emailhosting.order",
304	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
305	    },
306	  });
307	  revalidatePath("/dashboard/email");
308	  return { ok: true };
309	}
310	
311	// ---------- External-domain DNS setup + verification ----------
312	
313	/**
314	 * Return the DNS records a customer must publish at their registrar for an
315	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
316	 * ownership-verification record. Ownership-checked (caller must own the sub).
317	 *
318	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
319	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
320	 * note is returned so the panel still renders.
321	 */
322	export async function getEmailDnsRecords(
323	  subscriptionId: string,
324	): Promise<{ error?: string; records?: DnsRecord[]; verified?: boolean; external?: boolean }> {
325	  const user = await requireUser();
326	
327	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
328	  if (!sub) return { error: "Subscription not found." };
329	  if (sub.userId !== user.id) return { error: "Not your subscription." };
330	
331	  const domain = sub.domainName;
332	
333	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
334	  let dkimTxt = sub.dkimRecord ?? null;
335	  if (!dkimTxt && mailcowConfigured()) {
336	    try {
337	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
338	      if (!(await mcDomainExists(domain))) {
339	        await mcCreateDomain(domain).catch(() => {});
340	      }
341	      dkimTxt = await mcGetDkim(domain);
342	      if (dkimTxt) {
343	        await db.emailSubscription
344	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
345	          .catch(() => {});
346	      }
347	    } catch (e) {
348	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
349	    }
350	  }
351	
352	  const records: DnsRecord[] = [
353	    {
354	      type: "TXT",
355	      label: "Ownership verification",
356	      host: `_nxeon-verify.${domain}`,
357	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
358	      note: "Proves you control this domain. Required before mail is enabled.",
359	    },
360	    {
361	      type: "MX",
362	      label: "Mail routing (MX)",
363	      host: domain,
364	      value: MAIL_HOST,
365	      priority: MAIL_MX_PRIORITY,
366	    },
367	    {
368	      type: "TXT",
369	      label: "SPF",
370	      host: domain,
371	      value: SPF_VALUE,
372	      note: "Authorizes the Nxeon mail server to send for your domain.",
373	    },
374	    {
375	      type: "TXT",
376	      label: "DKIM",
377	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
378	      value: dkimTxt ?? "",
379	      note: dkimTxt
380	        ? undefined
381	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
382	    },
383	    {
384	      type: "TXT",
385	      label: "DMARC",
386	      host: `_dmarc.${domain}`,
387	      value: DMARC_VALUE,
388	      note: "Reporting policy for messages that fail SPF/DKIM.",
389	    },
390	  ];
391	
392	  return { records, verified: sub.verified, external: sub.external };
393	}
394	
395	/**
396	 * Verify that an EXTERNAL domain's owner has published our verification record.
397	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
398	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
399	 * corroboration. The result is derived entirely server-side from live DNS —
400	 * client input never decides the outcome. Rate-limited per user + subscription.
401	 */
402	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
403	  const user = await requireUser();
404	
405	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
406	  if (!sub) return { error: "Subscription not found." };
407	  if (sub.userId !== user.id) return { error: "Not your subscription." };
408	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
409	  if (sub.verified) return { ok: true };
410	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
411	
412	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
413	    max: 6,
414	    windowMs: 60_000,
415	  });
416	  if (!rl.ok) {
417	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
418	  }
419	
420	  const domain = sub.domainName;
421	  const expected = `nxeon-verify=${sub.verifyToken}`;
422	
423	  // Primary signal: the verification TXT record must contain our exact token.
424	  let tokenFound = false;
425	  try {
426	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
427	    // Each record may be split into multiple strings — join per-record chunks.
428	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
429	  } catch {
430	    tokenFound = false;
431	  }
432	
433	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
434	  let mxOk = false;
435	  try {
436	    const mx = await resolveMx(domain);
437	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
438	  } catch {
439	    mxOk = false;
440	  }
441	
442	  if (!tokenFound) {
443	    return {
444	      error: mxOk
445	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
446	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
447	    };
448	  }
449	
450	  await db.emailSubscription.update({
451	    where: { id: sub.id },
452	    data: { verified: true, verifiedAt: new Date() },
453	  });
454	
455	  await db.auditLog.create({
456	    data: {
457	      userId: user.id,
458	      action: "emailhosting.verify",
459	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
460	    },
461	  });
462	  revalidatePath("/dashboard/email");
463	  return { ok: true };
464	}
465	
466	// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
467	const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
468	
469	/**
470	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
471	 * quota and address uniqueness within the subscription, records the intended
472	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
473	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
474	 */
475	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
476	  const user = await requireUser();
477	
478	  const sub = await db.emailSubscription.findUnique({
479	    where: { id: subscriptionId },
480	    include: { emailPlan: true, mailboxes: true },
481	  });
482	  if (!sub) return { error: "Subscription not found." };
483	  if (sub.userId !== user.id) return { error: "Not your subscription." };
484	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
485	
486	  const local = String(localPart ?? "").trim().toLowerCase();
487	  if (!localPartRe.test(local) || local.length > 64) {
488	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
489	  }
490	
491	  const address = `${local}@${sub.domainName}`;
492	
493	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
494	    return {
495	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
496	    };
497	  }
498	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
499	    return { error: "That address already exists." };
500	  }
501	
502	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
503	  const quotaMB = sub.emailPlan.storageGB * 1024;
504	
505	  const mailbox = await db.mailbox.create({
506	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
507	  });
508	
509	  await db.auditLog.create({
510	    data: { userId: user.id, action: "mailbox.add", detail: address },
511	  });
512	
513	  // Additive, failure-tolerant provisioning — never throws out of the flow.
514	  await provisionMailboxOnMailcow({
515	    id: mailbox.id,
516	    address: mailbox.address,
517	    quotaMB,
518	    subscription: { domainName: sub.domainName },
519	  });
520	
521	  revalidatePath("/dashboard/email");
522	  return { ok: true };
523	}
524	
525	/**
526	 * Re-attempt Mailcow provisioning for a mailbox stuck in PROVISIONING/FAILED.
527	 * Owner-only (the caller must own the mailbox via its subscription).
528	 */
529	export async function retryMailboxProvision(mailboxId: string): Promise<Result> {
530	  const user = await requireUser();
531	
532	  const mailbox = await db.mailbox.findUnique({
533	    where: { id: mailboxId },
534	    include: { subscription: true },
535	  });
536	  if (!mailbox) return { error: "Mailbox not found." };
537	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
538	  if (!mailcowConfigured()) return { error: "Mail server is not configured yet." };
539	
540	  await db.mailbox.update({ where: { id: mailbox.id }, data: { status: "PROVISIONING" } });
541	
542	  const status = await provisionMailboxOnMailcow({
543	    id: mailbox.id,
544	    address: mailbox.address,
545	    quotaMB: mailbox.quotaMB,
546	    subscription: { domainName: mailbox.subscription.domainName },
547	  });
548	
549	  await db.auditLog.create({
550	    data: { userId: user.id, action: "mailbox.retry", detail: `${mailbox.address} → ${status}` },
551	  });
552	  revalidatePath("/dashboard/email");
553	
554	  if (status === "FAILED") return { error: "Provisioning failed again — check the mail server." };
555	  return { ok: true };
556	}
557	
558	/** Remove a mailbox the caller owns (via its subscription). */
559	export async function removeMailbox(mailboxId: string): Promise<Result> {
560	  const user = await requireUser();
561	
562	  const mailbox = await db.mailbox.findUnique({
563	    where: { id: mailboxId },
564	    include: { subscription: true },
565	  });
566	  if (!mailbox) return { error: "Mailbox not found." };
567	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
568	
569	  // Best-effort delete on Mailcow before dropping the row — a mail-server outage
570	  // must not block the customer from removing the mailbox record.
571	  if (mailcowConfigured()) {
