187	// ---------- DKIM ----------
188	
189	/**
190	 * Fetch the DKIM public-key TXT value for a domain from Mailcow
191	 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
192	 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
193	 * or null when the domain has no DKIM key yet or the shape is unexpected.
194	 *
195	 * Throws MailcowError only when the integration is unreachable/errors — callers
196	 * that must stay tolerant wrap this in try/catch.
197	 */
198	export async function mcGetDkim(domain: string): Promise<string | null> {
199	  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
200	  if (!res || typeof res !== "object") return null;
201	  // Mailcow returns {} for a domain with no key configured.
202	  const txt = (res as { dkim_txt?: unknown }).dkim_txt;
203	  if (typeof txt === "string" && txt.trim()) return txt.trim();
204	  return null;
205	}
