207	// ---------- Analytics ----------
208	
209	export type MailStats = {
210	  configured: true;
211	  domains: number;
212	  mailboxes: number;
213	  postfix: {
214	    sampled: number;
215	    sent: number;
216	    deferred: number;
217	    bounced: number;
218	    rejected: number;
219	    other: number;
220	  };
221	  rspamd: {
222	    sampled: number;
223	    actions: Record<string, number>;
224	    spam: number; // reject + add header + rewrite subject
225	    clean: number; // no action + greylist / soft reject
226	  };
227	};
228	
229	function asArray(v: unknown): unknown[] {
230	  if (Array.isArray(v)) return v;
231	  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
232	    return (v as { rows: unknown[] }).rows;
233	  }
234	  return [];
235	}
236	
237	/**
238	 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
239	 * deliverability view. Throws (MailcowError) if not configured or unreachable —
240	 * the admin page catches that and shows a graceful fallback.
241	 */
242	export async function mcStats(sample = 400): Promise<MailStats> {
243	  config(); // throws early with a clear message if not configured
244	
245	  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
246	    mcRequest("GET", "/get/domain/all").catch(() => []),
247	    mcRequest("GET", "/get/mailbox/all").catch(() => []),
248	    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
249	    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
250	  ]);
251	
252	  const postfixLogs = asArray(postfixRaw);
253	  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
254	  for (const entry of postfixLogs) {
255	    const msg = String(
256	      (entry as { message?: unknown })?.message ??
257	        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
258	        "",
259	    ).toLowerCase();
260	    if (msg.includes("status=sent")) postfix.sent++;
261	    else if (msg.includes("status=deferred")) postfix.deferred++;
262	    else if (msg.includes("status=bounced")) postfix.bounced++;
263	    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
264	    else postfix.other++;
265	  }
266	
267	  const rspamdLogs = asArray(rspamdRaw);
268	  const actions: Record<string, number> = {};
269	  let spam = 0;
270	  let clean = 0;
271	  for (const entry of rspamdLogs) {
272	    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
273	    actions[action] = (actions[action] ?? 0) + 1;
274	    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
275	    else clean++;
276	  }
277	
278	  return {
279	    configured: true,
280	    domains: asArray(domainsRaw).length,
281	    mailboxes: asArray(mailboxesRaw).length,
282	    postfix,
283	    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
284	  };
285	}
