// Cloudflare DNS API client (API-token auth).
//
// Plain server-side module (NO "use server") — safe to import from server
// actions and the worker; never bundled to the client. Talks to the Cloudflare
// v4 REST API using a customer-supplied API token (scoped to Zone → DNS → Edit
// for their zone). The token is passed in per call — this module never reads it
// from the environment or persists it.
//
// Every function throws a clear CloudflareError on a non-success response so
// callers can surface a friendly message; callers that must stay tolerant wrap
// these in try/catch.

const CF_API = "https://api.cloudflare.com/client/v4";

export class CloudflareError extends Error {
  constructor(
    message: string,
    public status?: number,
    public code?: number,
  ) {
    super(message);
    this.name = "CloudflareError";
  }
}

type CfEnvelope<T> = {
  success: boolean;
  errors?: { code: number; message: string }[];
  result: T;
};

/** Core request helper — attaches the bearer token, parses the v4 envelope and
 * throws CloudflareError on transport failure or a `success:false` payload. */
async function cfRequest<T>(
  token: string,
  method: "GET" | "POST" | "PUT",
  path: string,
  body?: unknown,
): Promise<T> {
  const url = `${CF_API}${path.startsWith("/") ? path : `/${path}`}`;

  let res: Response;
  try {
    res = await fetch(url, {
      method,
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: body === undefined ? undefined : JSON.stringify(body),
      cache: "no-store",
    });
  } catch (e) {
    throw new CloudflareError(
      `Cloudflare unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
    );
  }

  const text = await res.text();
  let parsed: CfEnvelope<T> | null = null;
  try {
    parsed = text ? (JSON.parse(text) as CfEnvelope<T>) : null;
  } catch {
    // fall through to a generic error below
  }

  if (!parsed || parsed.success !== true) {
    const first = parsed?.errors?.[0];
    // 403/9109 → token lacks permission or is invalid; surface a stable message.
    const msg = first?.message ?? `Cloudflare ${method} ${path} -> HTTP ${res.status}`;
    throw new CloudflareError(msg, res.status, first?.code);
  }

  return parsed.result;
}

/**
 * Confirm an API token is valid and active (`GET /user/tokens/verify`). Returns
 * true only when Cloudflare reports the token status as "active". Never throws
 * for an ordinary invalid/expired token — returns false — but rethrows a genuine
 * transport failure so the caller can distinguish "rejected" from "unreachable".
 */
export async function cfVerifyToken(token: string): Promise<boolean> {
  try {
    const result = await cfRequest<{ status?: string }>(token, "GET", "/user/tokens/verify");
    return String(result?.status ?? "").toLowerCase() === "active";
  } catch (e) {
    if (e instanceof CloudflareError && (e.status === 400 || e.status === 401 || e.status === 403)) {
      return false;
    }
    throw e;
  }
}

/**
 * Resolve a zone name (registrable domain) to its Cloudflare zone id, or null
 * when the token can't see a zone by that exact name. `GET /zones?name=<zone>`.
 */
export async function cfFindZoneId(token: string, zoneName: string): Promise<string | null> {
  const name = zoneName.trim().toLowerCase().replace(/\.$/, "");
  const result = await cfRequest<{ id: string; name: string }[]>(
    token,
    "GET",
    `/zones?name=${encodeURIComponent(name)}&status=active&per_page=5`,
  );
  const zone = Array.isArray(result)
    ? result.find((z) => z.name?.toLowerCase() === name) ?? result[0]
    : undefined;
  return zone?.id ?? null;
}

export type CfDnsInput = {
  type: "TXT" | "MX";
  /** Fully-qualified record name, e.g. `_dmarc.example.com` or the zone apex. */
  name: string;
  content: string;
  priority?: number;
};

export type CfUpsertResult = {
  name: string;
  type: "TXT" | "MX";
  action: "created" | "updated";
};

type CfRecord = { id: string; type: string; name: string; content: string; priority?: number };

// Strip surrounding quotes Cloudflare may echo on TXT content, for comparison.
function unquote(s: string): string {
  return s.trim().replace(/^"(.*)"$/s, "$1");
}

/**
 * Decide whether an existing record is "the same kind" as one we manage, so an
 * upsert updates it in place rather than creating a duplicate. TXT records are
 * matched by their leading tag (SPF/DKIM/DMARC/ownership), MX by the mail host
 * it points at — so we never clobber a customer's unrelated records at the apex.
 */
function sameKind(desired: CfDnsInput, existing: CfRecord): boolean {
  if (existing.type !== desired.type) return false;
  if (desired.type === "MX") {
    return unquote(existing.content).replace(/\.$/, "").toLowerCase() ===
      desired.content.replace(/\.$/, "").toLowerCase();
  }
  const want = desired.content.toLowerCase();
  const have = unquote(existing.content).toLowerCase();
  for (const tag of ["nxeon-verify=", "v=spf1", "v=dkim1", "v=dmarc1"]) {
    if (want.startsWith(tag)) return have.startsWith(tag);
  }
  // No recognised tag — fall back to an exact name+type match (single record).
  return true;
}

/**
 * Create or update each desired record in the given zone. For every record we
 * list the existing records at that exact name+type, update the one of the same
 * kind if present (PUT), else create a new one (POST). Returns one result row
 * per input describing what happened. Throws CloudflareError on API failure.
 */
export async function cfUpsertRecords(
  token: string,
  zoneId: string,
  records: CfDnsInput[],
): Promise<CfUpsertResult[]> {
  const out: CfUpsertResult[] = [];

  for (const rec of records) {
    const existing = await cfRequest<CfRecord[]>(
      token,
      "GET",
      `/zones/${zoneId}/dns_records?type=${rec.type}&name=${encodeURIComponent(rec.name)}&per_page=100`,
    );
    const match = Array.isArray(existing) ? existing.find((e) => sameKind(rec, e)) : undefined;

    const body: Record<string, unknown> = {
      type: rec.type,
      name: rec.name,
      content: rec.content,
      ttl: 1, // 1 = automatic
    };
    if (rec.type === "MX") body.priority = rec.priority ?? 10;

    if (match) {
      await cfRequest(token, "PUT", `/zones/${zoneId}/dns_records/${match.id}`, body);
      out.push({ name: rec.name, type: rec.type, action: "updated" });
    } else {
      await cfRequest(token, "POST", `/zones/${zoneId}/dns_records`, body);
      out.push({ name: rec.name, type: rec.type, action: "created" });
    }
  }

  return out;
}

