// ---------- Mailbox password (reveal / reset) ----------

/** A strong, URL-safe mailbox password (same generator used at provisioning). */
function generateMailboxPassword(): string {
  return randomBytes(18).toString("base64url");
}

/**
 * Reveal the stored (encrypted) password for a mailbox the caller owns, so they
 * can sign in to webmail. Owner-only (checked via the mailbox's subscription).
 * Lightly rate-limited to blunt scraping. Returns null-safe: if no password was
 * ever stored (e.g. Mailcow wasn't configured at provisioning) the caller is
 * told to reset instead. The plaintext is only ever returned to the owner.
 */
export async function revealMailboxPassword(
  mailboxId: string,
): Promise<{ error?: string; password?: string }> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };

  const rl = checkRateLimit(`mailbox-pwreveal:${user.id}:${mailbox.id}`, {
    max: 10,
    windowMs: 60_000,
  });
  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };

  const password = decryptSecret(mailbox.passwordEnc);
  if (!password) {
    return { error: "No stored password for this mailbox yet — use Reset password to set one." };
  }
  return { password };
}

/**
 * Generate a new strong password for a mailbox the caller owns, apply it on the
 * mail server (Mailcow), then persist the new encrypted value. Owner-only and
 * rate-limited. The mail-server call must succeed before we store the new value,
 * so a stored password always matches what actually authenticates. Returns the
 * new password once for the customer to copy.
 */
export async function resetMailboxPassword(
  mailboxId: string,
): Promise<{ error?: string; password?: string }> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
  if (!mailcowConfigured()) return { error: "Mail server is not configured yet." };

  const rl = checkRateLimit(`mailbox-pwreset:${user.id}:${mailbox.id}`, {
    max: 5,
    windowMs: 60_000,
  });
  if (!rl.ok) return { error: `Too many resets. Try again in ${rl.retryAfterSec}s.` };

  const password = generateMailboxPassword();

  try {
    await mcSetMailboxPassword(mailbox.address, password);
  } catch (e) {
    console.warn(`[mailcow] set password ${mailbox.address} failed:`, e);
    return { error: "Couldn't update the password on the mail server. Try again shortly." };
  }

  await db.mailbox.update({
    where: { id: mailbox.id },
    data: { passwordEnc: encryptSecret(password) },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.pwreset", detail: mailbox.address },
  });
  revalidatePath("/dashboard/email");
  return { password };
}

// ---------- Cloudflare auto-DNS (external domains) ----------

/**
 * Store a customer's Cloudflare API token (encrypted) so we can create their
 * mail DNS records for them. The token is verified against Cloudflare before it
 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
 */
export async function saveCloudflareToken(token: string): Promise<Result> {
  const user = await requireUser();

  const t = String(token ?? "").trim();
  if (!t) return { error: "Paste your Cloudflare API token." };
  if (t.length < 20 || t.length > 200) {
    return { error: "That doesn't look like a Cloudflare API token." };
  }

  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };

  let valid = false;
  try {
    valid = await cfVerifyToken(t);
  } catch (e) {
    console.warn("[cloudflare] token verify failed:", e);
    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
  }
  if (!valid) {
    return {
      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
    };
  }

  await db.user.update({
    where: { id: user.id },
    data: { cloudflareTokenEnc: encryptSecret(t) },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

/**
 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
 * customer's Cloudflare zone, using their stored token. Ownership-checked and
 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
 * gracefully with clear messages for invalid token / zone-not-found.
 */
export async function autoCreateEmailDns(
  subscriptionId: string,
): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };
  if (!sub.external) {
    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
  }

  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };

  const token = decryptSecret(user.cloudflareTokenEnc);
  if (!token) {
    return { error: "Connect your Cloudflare account first (paste an API token above)." };
  }

  // Same record set the customer would otherwise publish by hand.
  const dns = await getEmailDnsRecords(subscriptionId);
  if (dns.error) return { error: dns.error };
  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
  if (records.length === 0) {
    return { error: "No DNS records to create yet — try again in a moment." };
  }

  let zoneId: string | null;
  try {
    zoneId = await cfFindZoneId(token, sub.domainName);
  } catch (e) {
    if (e instanceof CloudflareError) {
      return { error: `Cloudflare error: ${e.message}` };
    }
    throw e;
  }
  if (!zoneId) {
    return {
      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
    };
  }

  let created: string[];
  try {
    const results = await cfUpsertRecords(
      token,
      zoneId,
      records.map((r) => ({
        type: r.type,
        name: r.host,
        content: r.value,
        priority: r.priority,
      })),
    );
    created = results.map((res) => {
      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
      return `${label} (${res.type}, ${res.action})`;
    });
  } catch (e) {
    if (e instanceof CloudflareError) {
      return {
        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
      };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "cloudflare.autodns",
      detail: `${sub.domainName} — ${created.length} record(s)`,
    },
  });
  revalidatePath("/dashboard/email");
  return { ok: true, created };
}

