/** Small copy-to-clipboard button (mailbox password reveal/reset). */
function CopyChip({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-secondary shrink-0 px-2 py-1 text-xs"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        } catch {
          /* clipboard blocked — no-op */
        }
      }}
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

function MailboxItem({ mailbox }: { mailbox: MailboxRow }) {
  const [pending, start] = useTransition();
  const [pwPending, startPw] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [password, setPassword] = useState<string | null>(null);
  const [pwNote, setPwNote] = useState<string | null>(null);

  function reveal() {
    setError(null);
    setPwNote(null);
    startPw(async () => {
      const res = await revealMailboxPassword(mailbox.id);
      if (res?.error) setError(res.error);
      else if (res?.password) {
        setPassword(res.password);
        setPwNote("Current password — use it to sign in at mail.nxeon.cloud.");
      }
    });
  }

  function resetPw() {
    if (!confirm(`Reset the password for ${mailbox.address}? The current password will stop working.`)) return;
    setError(null);
    setPwNote(null);
    startPw(async () => {
      const res = await resetMailboxPassword(mailbox.id);
      if (res?.error) setError(res.error);
      else if (res?.password) {
        setPassword(res.password);
        setPwNote("New password set — copy it now, it won't be shown again automatically.");
      }
    });
  }

  return (
    <div className="rounded-lg border border-white/[0.06] px-3 py-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-mono text-sm text-white">{mailbox.address}</span>
          <Badge tone="amber">Provisioning</Badge>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={reveal}>
            {pwPending ? "…" : password ? "Refresh password" : "Show password"}
          </button>
          <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={resetPw}>
            Reset password
          </button>
          <button
            className="btn-danger py-1 text-xs"
            disabled={pending}
            onClick={() => {
              if (!confirm(`Remove mailbox ${mailbox.address}?`)) return;
              setError(null);
              start(async () => {
                const res = await removeMailbox(mailbox.id);
                if (res?.error) setError(res.error);
              });
            }}
          >
            Remove
          </button>
        </div>
      </div>

      {error && <p className="mt-2 text-xs text-red-400">{error}</p>}

      {password && (
        <div className="mt-2 rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
          <div className="flex items-center gap-2">
            <code className="min-w-0 flex-1 truncate rounded bg-white/[0.04] px-2 py-1 font-mono text-xs text-slate-100">
              {password}
            </code>
            <CopyChip text={password} />
            <button
              type="button"
              className="btn-secondary shrink-0 px-2 py-1 text-xs"
              onClick={() => {
                setPassword(null);
                setPwNote(null);
              }}
            >
              Hide
            </button>
          </div>
          {pwNote && <p className="mt-1 text-[11px] text-slate-500">{pwNote}</p>}
        </div>
      )}
    </div>
  );
}

